<script>
        // Micro-interactions for password visibility
        document.querySelectorAll('[data-icon="visibility"]').forEach(icon => {
            icon.addEventListener('click', function() {
                const input = this.previousElementSibling;
                if (input.type === 'password') {
                    input.type = 'text';
                    this.innerText = 'visibility_off';
                } else {
                    input.type = 'password';
                    this.innerText = 'visibility';
                }
            });
        });

        // Floating particle effect background for modern feel
        const main = document.querySelector('main');
        for (let i = 0; i < 6; i++) {
            const dot = document.createElement('div');
            dot.className = 'absolute rounded-full opacity-10 pointer-events-none';
            const size = Math.random() * 300 + 100;
            dot.style.width = `${size}px`;
            dot.style.height = `${size}px`;
            dot.style.backgroundColor = i % 2 === 0 ? '#712ae2' : '#1f108e';
            dot.style.left = `${Math.random() * 100}%`;
            dot.style.top = `${Math.random() * 100}%`;
            dot.style.filter = 'blur(100px)';
            dot.style.zIndex = '0';
            main.appendChild(dot);
        }
    </script>
